def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out"""
    # Simple implementation to find first differing position
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if this is a replacement
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)
            # If lengths differ, it's insertion/deletion
            elif len(s_in) < len(s_out):
                # Insertion case - need to figure out what was inserted
                return (s_in[i], s_out[i:i+len(s_in)-len(s_out)+1] if len(s_in)-len(s_out)<0 else s_out[i], i)
            else:
                # Deletion case
                return (s_in[i:i-len(s_in)+len(s_out)+1] if len(s_in)-len(s_out)>0 else s_in[i], s_out[i], i)

    # If we get here, one string is prefix of other
    if len(s_in) != len(s_out):
        # Length difference - insertion/deletion
        if len(s_in) < len(s_out):
            return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in))
        else:
            return (s_in[len(s_out):], s_out[-1] if s_out else "", len(s_out))

    return ("", "", -1)  # No change

